import{_ as o,o as a,c as t,a5 as c}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 11 话 CSS 进阶技巧：散装高频军火库","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.11-pro-tips.md","filePath":"comics/css/EP.11-pro-tips.md","lastUpdated":1793421609000}'),i={name:"comics/css/EP.11-pro-tips.md"};function s(r,e,l,d,n,p){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-11-话-css-进阶技巧-散装高频军火库" tabindex="-1">漫画 · 第 11 话 CSS 进阶技巧：散装高频军火库 <a class="header-anchor" href="#漫画-·-第-11-话-css-进阶技巧-散装高频军火库" aria-label="Permalink to &quot;漫画 · 第 11 话 CSS 进阶技巧：散装高频军火库&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/11-pro-tips">docs/css/11-pro-tips.md</a> ｜ 原画：<a href="./EP.11-pro-tips.svg">EP.11-pro-tips.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。封面图加载前布局疯狂跳动、竖版视频被拉成圆脸、目录吸顶时灵时不灵——三个事故在同一天找上门。</li><li><strong>标签君</strong>：HTML5 结构师，摊开一排&quot;一格属性解决一类问题&quot;的技巧卡片，并预告 HTML 篇即将开播。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>本章是 CSS 篇收官，汇集十余个每个项目都会用到、却散落在各篇文档里的高频属性：宽高比、媒体适配、粘性定位、滚动捕捉、几何裁剪、键盘焦点。像素酱发现这些翻车事故的共同点——都只要一行属性就能解决，只是没人把它们摆在一起讲过。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三类经典事故：<code>&lt;img&gt;</code> 只给宽度没给高度，图片加载前浏览器无法预留空间，加载瞬间布局跳动（CLS）；竖版视频在横屏容器里被 <code>fill</code> 拉伸，人脸变形；导航写了 <code>position: sticky</code> 却不吸顶——往往不是属性失效，而是祖先链上的 <code>overflow: hidden</code> 改变了吸附参考系。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>六个一行属性对应六类问题：<code>aspect-ratio: 16/9</code> 让宽度响应式、高度自动成比例；<code>object-fit: cover</code> 保持比例填满并裁掉超出；<code>position: sticky</code> 在阈值前是 relative、到达后变 fixed，但始终占位；<code>scroll-snap-type</code> 让滚动停止时自动对齐到卡片；<code>clip-path: polygon</code> 做几何裁剪且裁剪区外不响应事件；<code>:focus-visible</code> 只在键盘导航时显示焦点环。同区还有 inset、accent-color、color-scheme、gap、pointer-events、backdrop-filter。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>组合用法：封面墙用 <code>aspect-ratio:16/9 + object-fit:cover</code> 让图位先占位、零 CLS，hover 放大交给 transform；长表格用 sticky 的 thead 吸顶、首列吸左形成冻结窗格（必须 <code>border-collapse: separate</code> + 不透明背景）；横滑卡片用原生 scroll-snap，触屏惯性与键盘全部免费支持；固定头站点补一个 <code>scroll-padding-top</code> 同时解决锚点与吸附遮挡，键盘焦点统一交给 <code>:focus-visible</code>。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>aspect-ratio 是偏好不是强制：内容能撑高盒子，硬锁比例配 <code>overflow:hidden</code>。</li><li>内容图用 <code>img + object-fit</code>（可读屏、可懒加载），装饰图才用背景；sticky 失效先查祖先链 overflow。</li><li>居中选型：流内 flex/grid，浮层 transform 回拉；别裸删 outline，用 <code>:focus-visible</code>。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：容器写了 <code>aspect-ratio: 1/1</code>，里面文字一多，正方形还是被撑高了，为什么？怎么锁死？</p><p><strong>答</strong>：aspect-ratio 是&quot;首选尺寸约束&quot;而非强制——它只在一个方向尺寸为 auto 时生效，而 <code>min-height: auto</code> 允许内容把盒子撑高（古老的 <code>padding-top:100%</code> hack 是 padding 算出的硬高度，没这个弹性）。锁死比例：给容器加 <code>overflow: hidden</code>，或显式 <code>max-height</code>，并给背景色避免图片加载前白块。这也是图位容器的推荐标配：<code>aspect-ratio + overflow:hidden + 底色</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>比例按钮 + object-fit 五态图墙（含 object-position 切换）：<a href="./../../examples/css/11-pro-tips/index-01-aspect-object.html">examples/css/11-pro-tips/index-01-aspect-object.html</a></li><li>sticky 吸顶目录（overflow 坑对照）+ 双粘性表格 + 四种居中方案：<a href="./../../examples/css/11-pro-tips/index-02-sticky-center.html">index-02-sticky-center.html</a></li><li>scroll-snap 轮播/分屏 + 自定义滚动条 + 平滑锚点：<a href="./../../examples/css/11-pro-tips/index-03-scroll-snap-bar.html">index-03-scroll-snap-bar.html</a></li><li>镂空字、clip-path 动效、focus-visible/accent-color/color-scheme、外边距折叠：<a href="./../../examples/css/11-pro-tips/index-04-blend-clip-misc.html">index-04-blend-clip-misc.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>CSS 篇完结！第 12 话《语义化标签》——HTML 篇开播：header、main、article、section 到底怎么分工，为什么搜索引擎和读屏器都在意它。</p>',22)])])}const f=o(i,[["render",s]]);export{m as __pageData,f as default};
